def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    components = []
    while cells:
        start = cells.pop()
        comp = [start]
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    p = (r + dr, c + dc)
                    if p in cells:
                        cells.remove(p)
                        comp.append(p)
                        stack.append(p)
        components.append(comp)
    components.sort(key=len, reverse=True)
    tile_comp, mask_comp = components[0], components[1]
    def bbox(comp):
        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        return min(rs), max(rs), min(cs), max(cs)
    tr0, tr1, tc0, tc1 = bbox(tile_comp)
    mr0, mr1, mc0, mc1 = bbox(mask_comp)
    tile = [row[tc0:tc1 + 1] for row in grid[tr0:tr1 + 1]]
    mask = [row[mc0:mc1 + 1] for row in grid[mr0:mr1 + 1]]
    th, tw = len(tile), len(tile[0])
    out = []
    for mask_row in mask:
        for tr in range(th):
            row = []
            for active in mask_row:
                row.extend(tile[tr] if active != bg else [bg] * tw)
            out.append(row)
    return out
